"""A bounded memo of an expensive score."""


class Scorer:
    def __init__(self, f, limit=64):
        self.f = f
        self.limit = limit
        self._seen = {}

    def score(self, x):
        key = tuple(x)
        if key not in self._seen:
            v = self.f(key)
            if len(self._seen) >= self.limit:
                self._seen.clear()
            self._seen[key] = v
        return self._seen[key]

    def size(self):
        return len(self._seen)

