"""An event log that records each event once and can be pruned."""


class Log:
    def __init__(self):
        self.events = []
        self.seen = set()

    def record(self, e):
        if e in self.seen:
            return False
        self.seen.add(e)
        self.events.append(e)
        return True

    def prune(self, keep_mod):
        for e in list(self.events):
            if e % keep_mod == 0:
                self.events.remove(e)
                self.seen.discard(e)

    def count(self):
        return len(self.events)

