"""Leases on named resources: a lease lasts a fixed term from when it is granted or renewed."""


class Leases:
    def __init__(self, term):
        self.term = term
        self.now = 0
        self.holder = {}
        self.until = {}
        self.granted = 0

    def advance(self, dt):
        self.now += dt
        self._sweep()

    def _sweep(self):
        for r in [r for r, t in self.until.items() if t <= self.now]:
            del self.until[r]
            del self.holder[r]

    def acquire(self, r, who):
        if r in self.holder and self.holder[r] != who:
            return False
        self.holder[r] = who
        self.until[r] = self.now + self.term
        self.granted += 1
        return True

    def renew(self, r, who):
        if self.holder.get(r) != who:
            return False
        self.until[r] = self.term
        self.until[r] = self.now + self.term
        return True

    def release(self, r, who):
        if self.holder.get(r) == who:
            del self.holder[r]
            del self.until[r]
            return True
        return False

    def owner(self, r):
        return self.holder.get(r)

    def snapshot(self):
        return (sorted(self.holder.items()), sorted(self.until.items()), self.granted)

