"""Leases on named resources: a lease lasts a fixed term from when it is granted or renewed."""


class Leases:
    def __init__(self, term):
        self.term = term
        self.now = 0
        self.holder = {}
        self.until = {}
        self.granted = 0

    def advance(self, dt):
        self.now += dt
        self._sweep()

    def _sweep(self):
        for r in [r for r, t in self.until.items() if t <= self.now]:
            del self.until[r]
            del self.holder[r]

    def acquire(self, r, who):
        if r in self.holder and self.holder[r] != who:
            return False
        self.holder[r] = who
        self.until[r] = self.now + self.term
        self.granted += 1
        return True

    def renew(self, r, who):
        if self.holder.get(r) != who:
            return False
        self.until[r] = self.now + self.term
        return True

    def release(self, r, who):
        if self.holder.get(r) == who:
            del self.holder[r]
            del self.until[r]
            return True
        return False

    def owner(self, r):
        return self.holder.get(r)

    def snapshot(self):
        return (sorted(self.holder.items()), sorted(self.until.items()), self.granted)

"""An undirected graph: adjacency sets and an edge count."""


class Graph:
    def __init__(self):
        self.adj = {}
        self.edges = 0

    def add_vertex(self, v):
        if v not in self.adj:
            self.adj[v] = set()

    def link(self, u, v):
        if u == v:
            raise ValueError('a loop')
        self.add_vertex(u)
        self.add_vertex(v)
        if v not in self.adj[u]:
            self.adj[u].add(v)
            self.adj[v].add(u)
            self.edges += 1

    def unlink(self, u, v):
        if v in self.adj.get(u, ()):
            self.adj[u].discard(v)
            self.adj[v].discard(u)
            self.edges -= 1

    def degree(self, v):
        return len(self.adj.get(v, ()))

    def neighbours(self, v):
        return sorted(self.adj.get(v, ()))

    def snapshot(self):
        return (sorted((k, sorted(n)) for k, n in self.adj.items()), self.edges)

"""Stock of items with reservations: what is available is what is held minus what is reserved."""


class Stock:
    def __init__(self):
        self.held = {}
        self.reserved = {}
        self.moves = 0

    def restock(self, item, n):
        self.held[item] = self.held.get(item, 0) + n
        self.reserved.setdefault(item, 0)
        self.moves += 1

    def reserve(self, item, n):
        if self.available(item) < n:
            return False
        self.moves += 1
        self.reserved[item] += n
        return True

    def release(self, item, n):
        n = min(n, self.reserved.get(item, 0))
        self.reserved[item] -= n
        self.moves += 1
        return n

    def ship(self, item, n):
        n = min(n, self.reserved.get(item, 0))
        self.reserved[item] -= n
        self.held[item] -= n
        self.moves += 1
        return n

    def available(self, item):
        return self.held.get(item, 0) - self.reserved.get(item, 0)

    def snapshot(self):
        return (sorted(self.held.items()), sorted(self.reserved.items()), self.moves)

