"""Bookings of time slots, with each person's slots indexed, and past slots dropped as time advances."""


class Calendar:
    def __init__(self):
        self.now = 0
        self.slot = {}
        self.mine = {}

    def advance(self, dt):
        self.now += dt
        self._drop_past()

    def _drop_past(self):
        for s in [s for s in self.slot if s < self.now]:
            who = self.slot.pop(s)
            self.mine[who].discard(s)

    def book(self, s, who):
        if s < self.now or s in self.slot:
            return False
        self.slot[s] = who
        self.mine.setdefault(who, set()).add(s)
        return True

    def cancel(self, s):
        who = self.slot.pop(s, None)
        if who is None:
            return False
        self.mine[who].discard(s)
        return True

    def slots_of(self, who):
        return sorted(self.mine.get(who, ()))

    def snapshot(self):
        return (sorted(self.slot.items()), sorted((w, sorted(v)) for w, v in self.mine.items() if v))

