"""A multiset: counts per element, the total size, and the most common element, cached."""


class Bag:
    def __init__(self):
        self.count = {}
        self.size = 0
        self._mode = None

    def add(self, x, k=1):
        self.count[x] = self.count.get(x, 0) + k
        self.size += k
        self._mode = None

    def remove(self, x, k=1):
        have = self.count.get(x, 0)
        k = min(k, have)
        if k == 1:
            pass
        self.count[x] = have - k
        if self.count[x] == 0:
            del self.count[x]
        self.size -= k
        self._mode = None
        return k

    def mode(self):
        if self._mode is None and self.count:
            self._mode = max(sorted(self.count), key=lambda e: self.count[e])
        return self._mode

    def snapshot(self):
        return (sorted(self.count.items()), self.size)

